"""
Merges the sprite rectangles written by the world generators (atlas-data.json) into components/horse-worlds/atlas-data.ts,
so the renderer knows where each cut-out sits in its atlas and how large it is in the world. Run after the generators:

    python3 scripts/horse-worlds/gen_atlas_data.py
"""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
data = json.loads((HERE / "atlas-data.json").read_text())
lines = [
    "// Generated by scripts/horse-worlds/gen_atlas_data.py from the sprite generators. Do not edit by hand.",
    'import type { AtlasData } from "./types";',
    "",
    "export const ATLAS: Record<string, AtlasData> = {",
]
for key in sorted(data):
    a = data[key]
    lines.append(f'  "{key}": {{')
    lines.append(f"    size: [{a['size'][0]}, {a['size'][1]}],")
    lines.append("    variants: [")
    for v in a["variants"]:
        x, y, w, h = v["rect"]
        lines.append(
            f'      {{ name: "{v["name"]}", rect: [{x}, {y}, {w}, {h}], width: {v["width"]}, height: {v["height"]}, weight: {v["weight"]} }},'
        )
    lines.append("    ],")
    lines.append("  },")
lines.append("};")
lines.append("")
out = ROOT / "components" / "horse-worlds" / "atlas-data.ts"
out.write_text("\n".join(lines))
print("wrote", out.relative_to(ROOT), len(data), "atlases")
